SUM[-1:-1]=['<h3>4.8 הקשר לפסקאות האחרות</h3>', '<p>פסקת ההגבלה פועלת יחד עם שמירת הדינים (חקיקה ישנה מוגנת), ההתגברות (בחופש העיסוק בלבד) והפרשנות המקיימת. בפועל, עורך דין בוחן קודם כול אם חל חוק יסוד, ואם נפגעה זכות מוגנת. רק אחר כך הוא עובר לפסקת ההגבלה, ואם היא נכשלת בוחן את הסעד: פסילה מיידית, בטלות מושהית או פרשנות מקיימת. הסדר הזה חוסך טעויות נפוצות, כגון דילוג על שלב הפגיעה.</p>']
